args<-commandArgs(TRUE);O<-args[1];P<-dirname(dirname(O));canon<-function(x){x<-toupper(trimws(x));a<-c(MRE11A='MRE11',ATP5A1='ATP5F1A',ATP5B='ATP5F1B',ATP5C1='ATP5F1C',ATP5G1='ATP5MC1',ATP5O='ATP5PO',PARK2='PRKN');j<-x%in%names(a);x[j]<-a[x[j]];x};lt<-readRDS(file.path(P,'00_raw/nichenet_v2_mouse/ligand_target_matrix_nsga2r_final_mouse.rds'));rownames(lt)<-canon(rownames(lt));colnames(lt)<-canon(colnames(lt));stopifnot(!anyDuplicated(rownames(lt)),!anyDuplicated(colnames(lt)));res<-lapply(seq_len(ncol(lt)),function(i){w<-lt[,i];ord<-order(-w,rownames(lt));ord<-head(ord[w[ord]>0],200);if(length(ord)==0)return(NULL);data.frame(ligand=colnames(lt)[i],gene=rownames(lt)[ord],weight=w[ord],prior_rank=seq_along(ord))});write.table(do.call(rbind,res),file.path(O,'inputs/top200_ligand_target_prior.tsv'),sep="\t",quote=FALSE,row.names=FALSE);writeLines(capture.output(sessionInfo()),file.path(O,'provenance/prior_R_session.txt'))